OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'transformer-station.glb')
bpy.ops.object.select_all(action='SELECT')
bpy.ops.object.delete(use_global=False)
for material in bpy.data.materials: bpy.data.materials.remove(material)
materials={}
for name, values in RECIPE['materials'].items():
 m=bpy.data.materials.new(name)
 m.diffuse_color=tuple(v/255 for v in values['color'])
 m.use_nodes=True
 bsdf=m.node_tree.nodes.get('Principled BSDF')
 bsdf.inputs['Base Color'].default_value=m.diffuse_color
 bsdf.inputs['Metallic'].default_value=values['metallic']
 bsdf.inputs['Roughness'].default_value=values['roughness']
 materials[name]=m

def to_blender(v):
 # glTF export turns Blender (X,Y,Z) -> glTF (X,Z,-Y)
 return (v[0], -v[2], v[1])
groups={key:[] for key in materials}
for p in RECIPE['primitives']:
 if p['kind']=='box':
  bpy.ops.mesh.primitive_cube_add(size=1)
  obj=bpy.context.object
  obj.dimensions=to_blender((p['size'][0],p['size'][2],p['size'][1])) if False else (p['size'][0],p['size'][2],p['size'][1])
 else:
  bpy.ops.mesh.primitive_cylinder_add(vertices=p['sections'],radius=p['radius'],depth=p['height'])
  obj=bpy.context.object
  # Cylinder default is aligned with Blender Z (export Y)
  if p['axis']=='X': obj.rotation_euler[1]=math.pi/2
  if p['axis']=='Z': obj.rotation_euler[0]=math.pi/2
 obj.name=p['name']
 obj.location=to_blender(p['center'])
 obj.data.materials.append(materials[p['group']])
 bpy.ops.object.transform_apply(location=False,rotation=True,scale=True)
 groups[p['group']].append(obj)
# Merge all subparts to one render mesh per material without changing geometry
for group,objects in groups.items():
 bpy.ops.object.select_all(action='DESELECT')
 for obj in objects: obj.select_set(True)
 bpy.context.view_layer.objects.active=objects[0]
 bpy.ops.object.join()
 objects[0].name=group
# Anchors remain transform-only objects / empty glTF nodes
for name,location in RECIPE['anchors'].items():
 empty=bpy.data.objects.new(name,None)
 bpy.context.collection.objects.link(empty)
 empty.empty_display_type='PLAIN_AXES'
 empty.empty_display_size=.06
 empty.location=to_blender(location)
# Root exported with transform identity, glTF Y-up conversion
bpy.ops.object.select_all(action='SELECT')
bpy.ops.export_scene.gltf(filepath=OUT,export_format='GLB',export_yup=True,export_apply=True,export_materials='EXPORT',export_cameras=False,export_lights=False,export_extras=True)
# Measured manifest based on Blender depsgraph objects prior to export
objs=[bpy.data.objects.get(g) for g in groups]
tris=sum(sum(len(p.vertices)-2 for p in o.data.polygons) for o in objs)
verts=[]
for o in objs:
 for corner in o.bound_box:
  world=o.matrix_world @ Vector(corner)
  verts.append((world.x,world.z,-world.y))
mins=[min(v[i] for v in verts) for i in range(3)]
maxs=[max(v[i] for v in verts) for i in range(3)]
manifest={'asset':'transformer-station.glb','dimensions_xyz_m':[maxs[i]-mins[i] for i in range(3)],'local_bounds':{'min':mins,'max':maxs},'triangle_count':tris,'material_groups':list(groups),'anchors':RECIPE['anchors'],'file_bytes':os.path.getsize(OUT),'provenance':'Original procedural geometry, built-in Blender shapes; no third-party assets','validation':{'blender_export_executed':True,'khronos_gltf_validator':'not run','exported_glb_independent_reimport':'not run'}}
with open(os.path.join(os.path.dirname(OUT),'blender_rebuild_manifest.json'),'w') as file:json.dump(manifest,file,indent=2)
print('Exported',OUT,manifest)
